import{_ as o,c as a,o as s,a7 as t}from"./chunks/framework.D0mml042.js";const p=JSON.parse('{"title":"Troubleshooting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),i={name:"reference/troubleshooting.md"};function n(r,e,l,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /virga/reference/troubleshooting.md for this page in Markdown format</div><h1 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h1><p>This guide provides solutions to common problems you might encounter while using Virga.</p><h2 id="_1-server-startup-configuration-issues" tabindex="-1">1. Server Startup &amp; Configuration Issues <a class="header-anchor" href="#_1-server-startup-configuration-issues" aria-label="Permalink to &quot;1. Server Startup &amp; Configuration Issues&quot;">​</a></h2><p>Problems related to starting the <code>virga-server</code>.</p><h3 id="fatal-error-config-validation-failed" tabindex="-1">Fatal error: config validation failed <a class="header-anchor" href="#fatal-error-config-validation-failed" aria-label="Permalink to &quot;Fatal error: config validation failed&quot;">​</a></h3><p>This is the most common startup error. It means your <code>config.yaml</code> file has an issue. The server performs several checks upon loading the configuration.</p><ul><li><p><strong><code>database path is required</code></strong>: Your <code>config.yaml</code> is missing the <code>database.path</code> field. Add it under the <code>database</code> section.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/virga.db&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sqlite3&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><p><strong><code>at least one listener is required</code></strong>: You must define at least one listener under the <code>listeners:</code> section.</p></li><li><p><strong><code>listener[0]: name is required</code></strong>: Every listener in your list must have a <code>name</code> field.</p></li><li><p><strong><code>listener[0]: invalid port number</code></strong>: The <code>port</code> for a listener must be a valid number (e.g., 1-65535).</p></li><li><p><strong><code>listener[0]: SSL enabled but missing cert/key</code></strong>: If you set <code>use_ssl: true</code> for a listener, you must provide valid paths for both <code>ssl.cert</code> and <code>ssl.key</code>.</p></li></ul><h3 id="address-already-in-use" tabindex="-1">Address already in use <a class="header-anchor" href="#address-already-in-use" aria-label="Permalink to &quot;Address already in use&quot;">​</a></h3><p>This error means another process is already using the port specified for a listener or the admin interface.</p><ul><li><strong>Solution</strong>: Identify and stop the conflicting process, or change the <code>port</code> in your <code>config.yaml</code> to an unused one.</li></ul><h2 id="_2-beacon-generation-issues" tabindex="-1">2. Beacon Generation Issues <a class="header-anchor" href="#_2-beacon-generation-issues" aria-label="Permalink to &quot;2. Beacon Generation Issues&quot;">​</a></h2><p>Problems encountered when using the <code>generate beacon</code> command in the CLI.</p><h3 id="llm-model-or-library-not-found" tabindex="-1">LLM model or library not found <a class="header-anchor" href="#llm-model-or-library-not-found" aria-label="Permalink to &quot;LLM model or library not found&quot;">​</a></h3><p>This is the most common issue when generating an AI-enabled beacon.</p><ul><li><strong>Symptom</strong>: The command fails with an error message like <code>llama library not found</code> or <code>llama model not found</code>.</li><li><strong>Cause</strong>: The required AI model and platform-specific libraries have not been downloaded.</li><li><strong>Solution</strong>: Run the following command from the project&#39;s root directory on the machine running the Virgaer:<div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download-llama-deps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h3 id="cross-compilation-errors-cgo" tabindex="-1">Cross-Compilation Errors (CGO) <a class="header-anchor" href="#cross-compilation-errors-cgo" aria-label="Permalink to &quot;Cross-Compilation Errors (CGO)&quot;">​</a></h3><ul><li><strong>Symptom</strong>: The build fails with CGO-related errors, especially when generating a beacon for a different operating system (e.g., building a Windows beacon from Linux).</li><li><strong>Cause</strong>: Generating a beacon with AI features (<code>--enable-llama</code>) requires CGO. Cross-compiling CGO applications requires a specific toolchain.</li><li><strong>Solution</strong>: Install the appropriate cross-compiler on your system. For example, to build for Windows from a Debian/Ubuntu system, you need <code>mingw-w64</code>:<div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mingw-w64</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h2 id="_3-beacon-runtime-connectivity-issues" tabindex="-1">3. Beacon Runtime &amp; Connectivity Issues <a class="header-anchor" href="#_3-beacon-runtime-connectivity-issues" aria-label="Permalink to &quot;3. Beacon Runtime &amp; Connectivity Issues&quot;">​</a></h2><p>Problems after a beacon has been generated and deployed to a target.</p><h3 id="beacon-does-not-connect-no-session-appears" tabindex="-1">Beacon does not connect / No session appears <a class="header-anchor" href="#beacon-does-not-connect-no-session-appears" aria-label="Permalink to &quot;Beacon does not connect / No session appears&quot;">​</a></h3><ul><li><strong>Connectivity</strong>: Ensure the target machine can reach the C2 server and port specified during beacon generation. Check firewalls, network ACLs, and routing.</li><li><strong>Listener Mismatch</strong>: Double-check that a listener is active on the server that matches the protocol, port, and host embedded in the beacon.</li><li><strong>Encryption Key Mismatch</strong>: The encryption key is set on the <em>listener</em> in the server&#39;s <code>config.yaml</code>. The beacon will be generated to use this key. If you change the key on the server, you must regenerate the beacon.</li><li><strong>SSL/TLS Errors</strong>: If using an <code>https</code> listener, ensure the target machine trusts the SSL certificate used by the server. For testing, self-signed certificates will often cause the connection to fail unless the beacon is specifically configured to ignore certificate errors (a feature not yet implemented).</li></ul><h3 id="ai-features-fail-on-target" tabindex="-1">AI Features Fail on Target <a class="header-anchor" href="#ai-features-fail-on-target" aria-label="Permalink to &quot;AI Features Fail on Target&quot;">​</a></h3><ul><li><strong>Symptom</strong>: The beacon connects, but <code>llama</code> commands fail or the AI does not behave as expected.</li><li><strong>Cause 1</strong>: The beacon was not built with AI capabilities. <ul><li><strong>Solution</strong>: Ensure you generated the beacon using the <code>--enable-llama</code> flag or with <code>llama.enabled: true</code> in your <code>beacon.yaml</code>.</li></ul></li><li><strong>Cause 2</strong>: Insufficient memory on the target machine. <ul><li><strong>Solution</strong>: The AI model requires at least 2-4 GB of free RAM to load. The beacon may crash if the target does not have enough memory.</li></ul></li></ul><h2 id="_4-cli-usage-issues" tabindex="-1">4. CLI Usage Issues <a class="header-anchor" href="#_4-cli-usage-issues" aria-label="Permalink to &quot;4. CLI Usage Issues&quot;">​</a></h2><h3 id="cannot-connect-to-server" tabindex="-1">Cannot connect to server <a class="header-anchor" href="#cannot-connect-to-server" aria-label="Permalink to &quot;Cannot connect to server&quot;">​</a></h3><ul><li><strong>Symptom</strong>: The CLI fails to connect, showing a connection refused error.</li><li><strong>Cause</strong>: You might be trying to connect to a <em>listener</em> port instead of the <em>admin</em> port.</li><li><strong>Solution</strong>: Ensure the <code>--host</code> and <code>--port</code> flags for the CLI point to the <code>admin_port</code> defined in the server&#39;s <code>config.yaml</code> (default: 8443), not a beacon listener port (like 80 or 443).</li></ul><h3 id="no-active-session-error" tabindex="-1">&quot;No active session&quot; error <a class="header-anchor" href="#no-active-session-error" aria-label="Permalink to &quot;&quot;No active session&quot; error&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Commands like <code>exec</code> or <code>ls</code> fail with this error.</li><li><strong>Cause</strong>: These commands operate within the context of a specific session. You have not selected one yet.</li><li><strong>Solution</strong>: First, list the available sessions with <code>sessions list</code>. Then, select one to interact with using <code>interact &lt;session_id&gt;</code>.</li></ul>`,29)])])}const g=o(i,[["render",n]]);export{p as __pageData,g as default};
